import Foundation

struct ProblemExample: Codable, Hashable {
    let input: String
    let output: String
    let explanation: String?
}

/// One Blind 75 problem, decoded from Resources/problems.json (generated by content/build_problems.py).
/// The JSON also holds the test cases, driver and compare mode; only runner.py reads those.
struct Problem: Codable, Identifiable, Hashable {
    let id: Int
    let slug: String
    let title: String
    let lc: Int
    let difficulty: String
    let category: String
    let params: [String]
    let description: String
    let examples: [ProblemExample]
    let constraints: [String]
    let starter: String
    let hints: [String]
    let solution: String
    let complexity: String

    var difficultyRank: Int { ["Easy": 0, "Medium": 1, "Hard": 2][difficulty] ?? 3 }

    var categoryEmoji: String { Problem.categoryEmoji[category] ?? "✨" }

    static let categoryOrder = [
        "Arrays & Hashing", "Two Pointers", "Sliding Window", "Stack", "Binary Search", "Linked List",
        "Trees", "Tries", "Heap / Priority Queue", "Backtracking", "Graphs", "Advanced Graphs",
        "1-D Dynamic Programming", "2-D Dynamic Programming", "Greedy", "Intervals",
        "Math & Geometry", "Bit Manipulation",
    ]

    static let categoryEmoji: [String: String] = [
        "Arrays & Hashing": "🧺", "Two Pointers": "👯‍♀️", "Sliding Window": "🪟", "Stack": "🥞",
        "Binary Search": "🔍", "Linked List": "🔗", "Trees": "🌳", "Tries": "🌷",
        "Heap / Priority Queue": "⛰️", "Backtracking": "🧶", "Graphs": "🕸️", "Advanced Graphs": "🌌",
        "1-D Dynamic Programming": "🧁", "2-D Dynamic Programming": "🍰", "Greedy": "🍓",
        "Intervals": "📅", "Math & Geometry": "📐", "Bit Manipulation": "💡",
    ]

    static func loadAll() -> [Problem] {
        guard let url = ResourceLocator.url(for: "problems.json"),
              let data = try? Data(contentsOf: url),
              let problems = try? JSONDecoder().decode([Problem].self, from: data)
        else {
            NSLog("Leetling: could not load problems.json")
            return []
        }
        return problems.sorted { $0.id < $1.id }
    }
}

/// Finds bundled resources whether we're running from Leetling.app or via `swift run`.
enum ResourceLocator {
    static func url(for name: String) -> URL? {
        if let url = Bundle.main.resourceURL?.appendingPathComponent(name),
           FileManager.default.fileExists(atPath: url.path) {
            return url
        }
        // Development fallback: <repo>/Resources/<name>
        let repo = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
        let dev = repo.appendingPathComponent("Resources").appendingPathComponent(name)
        return FileManager.default.fileExists(atPath: dev.path) ? dev : nil
    }
}

// MARK: - Run results (mirrors runner.py's JSON output)

struct TestResult: Codable, Identifiable, Hashable {
    let index: Int
    let hidden: Bool
    let input: String
    let expected: String
    let output: String
    let stdout: String
    let error: String
    let passed: Bool
    var id: Int { index }
}

struct RunResult: Codable, Hashable {
    let status: String   // accepted | wrong_answer | runtime_error | time_limit | syntax_error | (app-side) setup_error
    let passed: Int
    let total: Int
    let results: [TestResult]
    let message: String
    let runtime_ms: Int?

    var accepted: Bool { status == "accepted" }

    var title: String {
        switch status {
        case "accepted": return "Accepted"
        case "wrong_answer": return "Wrong Answer"
        case "runtime_error": return "Runtime Error"
        case "time_limit": return "Time Limit Exceeded"
        case "syntax_error": return "Syntax Error"
        default: return "Couldn't run your code"
        }
    }

    var emoji: String {
        switch status {
        case "accepted": return "🌸"
        case "wrong_answer": return "🤔"
        case "time_limit": return "🐢"
        case "syntax_error": return "✏️"
        default: return "🩹"
        }
    }

    static func setupError(_ message: String) -> RunResult {
        RunResult(status: "setup_error", passed: 0, total: 0, results: [], message: message, runtime_ms: nil)
    }
}
